package com.digitalhealth.controller;
import com.digitalhealth.dto.AppointmentDTO; import com.digitalhealth.service.AppointmentService; import com.digitalhealth.security.AccessService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/workers/{workerId}/appointments") @CrossOrigin(originPatterns={"http://localhost:*","http://127.0.0.1:*"}) public class AppointmentController {private final AppointmentService service;private final AccessService access;public AppointmentController(AppointmentService s,AccessService a){service=s;access=a;}@PostMapping @ResponseStatus(HttpStatus.CREATED) public AppointmentDTO book(@PathVariable Long workerId,@Valid @RequestBody AppointmentDTO d){access.workerOrAdmin(workerId);return service.book(workerId,d);}@GetMapping public List<AppointmentDTO> list(@PathVariable Long workerId){access.clinicalAccess(workerId);return service.list(workerId);}@PatchMapping("/{id}/status") public AppointmentDTO status(@PathVariable Long workerId,@PathVariable Long id,@RequestParam String status){if("CANCELLED".equals(status))access.workerOrAdmin(workerId);else {access.providerOrAdmin();access.clinicalAccess(workerId);}return service.status(workerId,id,status);}}
